// Parse MQTT message and validate
try {
    const data = msg.payload;

    // Validate required fields
    if (!data.unitId || data.temperature === undefined || 
        data.humidity === undefined || !data.compressorStatus || 
        data.energyConsumption === undefined) {
        node.warn('Invalid data format: ' + JSON.stringify(data));
        return null;
    }

    // Store original data
    msg.sensorData = {
        unitId: data.unitId,
        temperature: parseFloat(data.temperature),
        humidity: parseFloat(data.humidity),
        compressorStatus: data.compressorStatus,
        energyConsumption: parseFloat(data.energyConsumption),
        timestamp: data.timestamp || new Date().toISOString()
    };

    // Set unit ID for routing
    msg.unitId = data.unitId;
    msg.topic = data.unitId;

    return msg;

} catch (error) {
    node.error('Parse error: ' + error.message, msg);
    return null;
}

const data = msg.sensorData;

// Prepare InfluxDB line protocol
const measurement = 'sensor_data';
const tags = `unitId=${data.unitId}`;
const fields = [
    `temperature=${data.temperature}`,
    `humidity=${data.humidity}`,
    `compressorStatus="${data.compressorStatus}"`,
    `energyConsumption=${data.energyConsumption}`
].join(',');

// Convert timestamp to nanoseconds
const timestampNs = new Date(data.timestamp).getTime() * 1000000;

msg.payload = `${measurement},${tags} ${fields} ${timestampNs}`;
msg.bucket = 'cold_storage';

return msg;

const data = msg.sensorData;
const unitId = data.unitId;

// Determine status based on thresholds
const tempStatus = data.temperature > 8 ? 'critical' :
                   data.temperature > 6 ? 'warning' : 'normal';

const humidityStatus = (data.humidity > 80 || data.humidity < 50) ? 'warning' : 'normal';

const energyEfficiency = data.energyConsumption > 4 ? 'critical' :
                         data.energyConsumption > 3 ? 'inefficient' : 'normal';

// Prepare Ditto PATCH payload
const dittoPayload = {
    features: {
        temperature: {
            properties: {
                value: data.temperature,
                status: tempStatus,
                lastUpdated: data.timestamp
            }
        },
        humidity: {
            properties: {
                value: data.humidity,
                status: humidityStatus,
                lastUpdated: data.timestamp
            }
        },
        compressor: {
            properties: {
                status: data.compressorStatus,
                lastUpdated: data.timestamp
            }
        },
        energy: {
            properties: {
                consumption: data.energyConsumption,
                efficiency: energyEfficiency,
                lastUpdated: data.timestamp
            }
        },
        connectivity: {
            properties: {
                connected: true,
                lastSeen: data.timestamp
            }
        }
    }
};

msg.payload = dittoPayload;
msg.url = `http://ditto-gateway:8080/api/2/things/org.eclipse.ditto:${unitId}`;
msg.method = 'PATCH';
msg.headers = {
    'Content-Type': 'application/merge-patch+json'
};

return msg;

const data = msg.sensorData;
const alerts = [];

// Temperature thresholds
const TEMP_CRITICAL_HIGH = 10.0;
const TEMP_WARNING_HIGH = 8.0;
const TEMP_WARNING_LOW = 2.0;
const TEMP_CRITICAL_LOW = 0.0;

// Humidity thresholds
const HUMIDITY_HIGH = 80;
const HUMIDITY_LOW = 50;

// Energy threshold
const ENERGY_WARNING = 3.0;
const ENERGY_CRITICAL = 4.0;

// Check temperature
if (data.temperature >= TEMP_CRITICAL_HIGH) {
    alerts.push({
        unitId: data.unitId,
        alertType: 'temperature_critical_high',
        severity: 'critical',
        message: `Temperature critically high: ${data.temperature}°C`,
        value: data.temperature,
        threshold: TEMP_CRITICAL_HIGH,
        timestamp: data.timestamp
    });
} else if (data.temperature >= TEMP_WARNING_HIGH) {
    alerts.push({
        unitId: data.unitId,
        alertType: 'temperature_warning_high',
        severity: 'warning',
        message: `Temperature above normal: ${data.temperature}°C`,
        value: data.temperature,
        threshold: TEMP_WARNING_HIGH,
        timestamp: data.timestamp
    });
} else if (data.temperature <= TEMP_CRITICAL_LOW) {
    alerts.push({
        unitId: data.unitId,
        alertType: 'temperature_critical_low',
        severity: 'critical',
        message: `Temperature critically low: ${data.temperature}°C`,
        value: data.temperature,
        threshold: TEMP_CRITICAL_LOW,
        timestamp: data.timestamp
    });
} else if (data.temperature <= TEMP_WARNING_LOW) {
    alerts.push({
        unitId: data.unitId,
        alertType: 'temperature_warning_low',
        severity: 'warning',
        message: `Temperature below normal: ${data.temperature}°C`,
        value: data.temperature,
        threshold: TEMP_WARNING_LOW,
        timestamp: data.timestamp
    });
}

// Check humidity
if (data.humidity > HUMIDITY_HIGH || data.humidity < HUMIDITY_LOW) {
    alerts.push({
        unitId: data.unitId,
        alertType: 'humidity_out_of_range',
        severity: 'warning',
        message: `Humidity out of range: ${data.humidity}%`,
        value: data.humidity,
        threshold: data.humidity > HUMIDITY_HIGH ? HUMIDITY_HIGH : HUMIDITY_LOW,
        timestamp: data.timestamp
    });
}

// Check energy consumption
if (data.energyConsumption >= ENERGY_CRITICAL) {
    alerts.push({
        unitId: data.unitId,
        alertType: 'energy_critical',
        severity: 'critical',
        message: `Energy consumption critically high: ${data.energyConsumption}kW`,
        value: data.energyConsumption,
        threshold: ENERGY_CRITICAL,
        timestamp: data.timestamp
    });
} else if (data.energyConsumption >= ENERGY_WARNING) {
    alerts.push({
        unitId: data.unitId,
        alertType: 'energy_warning',
        severity: 'warning',
        message: `Energy consumption elevated: ${data.energyConsumption}kW`,
        value: data.energyConsumption,
        threshold: ENERGY_WARNING,
        timestamp: data.timestamp
    });
}

// If alerts exist, send them
if (alerts.length > 0) {
    msg.alerts = alerts;
    msg.sensorData = data;
    return msg;
}

return null;

const alerts = msg.alerts || [];
const outputs = [];

for (const alert of alerts) {
    // Prepare alert message for each alert
    const alertMsg = {
        payload: alert,
        topic: `coldstorage/${alert.unitId}/alerts`
    };
    outputs.push(alertMsg);
}

return [outputs];

const alert = msg.payload;

const measurement = 'alerts';
const tags = `unitId=${alert.unitId},alertType=${alert.alertType},severity=${alert.severity}`;
const fields = [
    `message="${alert.message}"`,
    `value=${alert.value}`,
    `threshold=${alert.threshold}`,
    `resolved=false`
].join(',');

const timestampNs = new Date(alert.timestamp).getTime() * 1000000;

msg.payload = `${measurement},${tags} ${fields} ${timestampNs}`;
msg.bucket = 'alerts';

return msg;
